<?php
$error=null;
if(is_post()){
 try{
  switch(post('action')){
   case 'request': if(!has_role('Sales','Executive Officer')) throw new UserError('Only Sales Staff or an Executive Officer can request a customer return.'); SalesWorkflowService::requestSalesReturn(uid(),(int)post('sale_id'),post_rows('lines'),post('reason')); flash('ok','Sales return submitted for Executive Officer approval.'); break;
   case 'refund': if(!has_role('Sales','Executive Officer')) throw new UserError('Only Sales Staff or an Executive Officer can process an approved refund.'); SalesWorkflowService::processSalesRefund((int)post('return_id'),uid(),post('method'),post('reference_no'),post('approver_employee_id'),post('approver_password')); flash('ok','Refund processed and the approved inventory effect has been recorded.'); break;
   default: throw new UserError('Unknown return action.');
  }
  redirect('sales_returns');
 }catch(Throwable $e){$error=friendly_error($e);}
}
$returnDays=(int)setting('sales_return_days',7);
$sales=q_all("SELECT s.sale_id,s.sale_ref_no,s.or_number,s.amount_due,s.customer_name,s.recorded_by,sd.business_date FROM sales s JOIN drawer_sessions ds ON ds.session_id=s.session_id JOIN sales_days sd ON sd.sales_day_id=ds.sales_day_id
               WHERE s.sale_type='Counter Sale' AND s.status IN ('Completed','Partially Returned') AND sd.business_date >= ? ".(has_role('Executive Officer')?'':'AND s.recorded_by='.(int)uid())." ORDER BY s.sale_id DESC LIMIT 300",[date('Y-m-d',strtotime("-$returnDays days"))]);
$selected=(int)($_GET['sale_id']??0); $selectedSale=$selected?q_one("SELECT recorded_by FROM sales WHERE sale_id=?",[$selected]):null; if($selected && (!$selectedSale || ((int)$selectedSale['recorded_by']!==uid() && !has_role('Executive Officer')))) { http_response_code(403); render_message('Sale restricted','You can request a return only for a sale you recorded.'); exit; } $lines=$selected?SalesWorkflowService::saleLinesForReturn($selected):[];
$pending=has_role('Executive Officer')?SalesWorkflowService::pendingReturns():[];
$refunds=has_role('Sales','Executive Officer')?q_all("SELECT sr.sales_return_id,sr.refund_amount,sr.status,s.sale_ref_no,s.or_number,rf.refund_id FROM sales_returns sr LEFT JOIN sales s ON s.sale_id=sr.sale_id LEFT JOIN refunds rf ON rf.sales_return_id=sr.sales_return_id WHERE sr.recorded_by=? ORDER BY sr.sales_return_id DESC LIMIT 20",[uid()]):[];
layout_start('Sales returns','Returns are line-level. Executive Officer approval is required before the refund and stock effect are processed.'); echo error_box($error);
?>
<?php if(has_role('Sales','Executive Officer')):?><section class="panel"><h2>Request a customer return</h2><form method="get" class="filters"><input type="hidden" name="page" value="sales_returns"><div><label>Sale (last <?=e($returnDays)?> days)</label><select name="sale_id"><option value="">Select sale</option><?php foreach($sales as $s):?><option value="<?=e($s['sale_id'])?>"<?= $selected===$s['sale_id']?' selected':''?>><?=e($s['sale_ref_no'])?> · OR <?=e($s['or_number'])?> · <?=e(fmt_d($s['business_date']))?> · <?=e($s['customer_name'])?> · <?=e(money($s['amount_due']))?></option><?php endforeach;?></select></div><button class="btn btn-secondary">Load lines</button></form><?php if($selected && !$lines):?><div class="empty">No returnable item lines remain on that sale.</div><?php elseif($selected):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="request"><input type="hidden" name="sale_id" value="<?=e($selected)?>"><div class="table-wrap"><table><thead><tr><th>Item</th><th>Sold / returnable</th><th>Return qty</th><th>Condition</th></tr></thead><tbody><?php foreach($lines as $x):?><tr><td><?=e($x['name'])?></td><td><?=e(qty($x['qty']))?> / <?=e(qty($x['qty_returnable']))?> <?=e($x['unit_of_measure'])?></td><td><input name="lines[<?=e($x['sale_line_id'])?>][sale_line_id]" type="hidden" value="<?=e($x['sale_line_id'])?>"><input name="lines[<?=e($x['sale_line_id'])?>][qty]" type="number" min="0" max="<?=e($x['qty_returnable'])?>" step="0.01"></td><td><select name="lines[<?=e($x['sale_line_id'])?>][condition]"><option>Resellable</option><option>Damaged/Defective</option></select></td></tr><?php endforeach;?></tbody></table></div><div class="form-grid"><div class="full"><label>Reason</label><textarea name="reason" required></textarea></div></div><button class="btn btn-primary">Submit return request</button></form><?php endif;?></section><?php endif; ?>
<?php if(has_role('Executive Officer')):?><section class="panel"><h2>Pending return approvals</h2><?php if(!$pending):?><div class="empty">No pending returns.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Sale</th><th>Customer</th><th>Refund</th><th>Reason</th></tr></thead><tbody><?php foreach($pending as $x):?><tr><td><?=e($x['sale_ref_no'])?><span class="sub"><?=e($x['or_number'])?></span></td><td><?=e($x['customer_name'])?></td><td><?=e(money($x['refund_amount']))?></td><td><?=e($x['reason'])?></td></tr><?php endforeach;?></tbody></table></div><p><a class="btn btn-secondary" href="<?=e(url('approvals'))?>">Open approvals queue</a></p><?php endif;?></section><?php endif; ?>
<?php if(has_role('Sales','Executive Officer')):?><section class="panel"><h2>Your recent returns</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Sale</th><th>Refund</th><th>Status</th><th>Refund processing</th></tr></thead><tbody><?php if(!$refunds):?><tr><td colspan="5"><div class="empty">You have no customer returns yet.</div></td></tr><?php endif;?><?php foreach($refunds as $x):?><tr><td>#<?=e($x['sales_return_id'])?></td><td><?=e($x['sale_ref_no'])?><span class="sub"><?=e($x['or_number'])?></span></td><td><?=e(money($x['refund_amount']))?></td><td><?=status_badge($x['status'])?></td><td><?php if($x['status']==='Approved' && !$x['refund_id']):?><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="refund"><input type="hidden" name="return_id" value="<?=e($x['sales_return_id'])?>"><select name="method"><option>Cash</option><option>GCash</option><option>Bank Transfer</option></select><input type="text" name="reference_no" placeholder="Reference if non-cash"><input type="text" name="approver_employee_id" placeholder="Executive Officer ID" required><input name="approver_password" type="password" placeholder="Executive Officer password" required><button class="btn btn-primary btn-sm">Process refund</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif; ?>
<?php layout_end();
